#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <iostream>
using namespace fedspatial;static bool ld(const std::string&n,Matrix*x){return read_matrix("sync_gpu/tests/fixtures/sync_gpu/"+n,x);}int main(){Matrix k(2,2),s(3,2),z(3,1),x(3,1),g(1,1),mu(2,1),sg(2,2);double a[]={0,0,1,.2,.3,1.1},b[]={0,0,1.5,1.5},q[]={1.2,-.4,.7};std::copy(a,a+6,s.a.begin());std::copy(b,b+4,k.a.begin());std::copy(q,q+3,z.a.begin());for(double&v:x.a)v=1;g(0,0)=.15;mu(0,0)=.2;mu(1,0)=-.1;sg(0,0)=.7;sg(1,1)=.4;sg(0,1)=sg(1,0)=.05;GpuContext c(0);double ed=0,ea=0,er=0;for(int i=0;i<7;i++){Matrix p,d,a,r;if(!ld("DELTA_THETA_POINT"+std::to_string(i)+"_PARAM.txt",&p)||!ld("DELTA_THETA_POINT"+std::to_string(i)+"_M_GRAD_DELTA.txt",&d)||!ld("DELTA_THETA_POINT"+std::to_string(i)+"_M_GRAD_ALPHA.txt",&a)||!ld("DELTA_THETA_POINT"+std::to_string(i)+"_M_GRAD_RANGE.txt",&r))return 2;auto m=compute_m_first_derivatives(c,{s,z,x},k,{g,mu,sg,p(0,0),p(1,0),p(2,0)});ed=std::max(ed,max_abs_diff(m.delta,d));ea=std::max(ea,max_abs_diff(m.alpha,a));er=std::max(er,max_abs_diff(m.range,r));}double mx=std::max({ed,ea,er});std::cout<<"M_GRAD_DELTA_MAX_ABS_ERROR="<<ed<<"\nM_GRAD_ALPHA_MAX_ABS_ERROR="<<ea<<"\nM_GRAD_RANGE_MAX_ABS_ERROR="<<er<<"\nM_GRAD_MAX_ABS_ERROR="<<mx<<"\nM_GRAD_PARITY="<<(mx<=1e-10?"PASS":"FAIL")<<"\n";return mx<=1e-10?0:1;}
